changeSet.sql:
ALTER TABLE business ADD COLUMN IF NOT EXISTS mobile varchar(10);
ALTER TABLE business ADD COLUMN IF NOT EXISTS gst_number varchar(15);
ALTER TABLE business ADD COLUMN IF NOT EXISTS billing_line_1 varchar(200);
ALTER TABLE business ADD COLUMN IF NOT EXISTS billing_line_2 varchar(200);
ALTER TABLE business ADD COLUMN IF NOT EXISTS billing_city varchar(120);
ALTER TABLE business ADD COLUMN IF NOT EXISTS billing_state varchar(80);
ALTER TABLE business ADD COLUMN IF NOT EXISTS billing_pincode varchar(6);
ALTER TABLE business ADD COLUMN IF NOT EXISTS shipping_line_1 varchar(200);
ALTER TABLE business ADD COLUMN IF NOT EXISTS shipping_line_2 varchar(200);
ALTER TABLE business ADD COLUMN IF NOT EXISTS shipping_city varchar(120);
ALTER TABLE business ADD COLUMN IF NOT EXISTS shipping_state varchar(80);
ALTER TABLE business ADD COLUMN IF NOT EXISTS shipping_pincode varchar(6);
ALTER TABLE business ADD COLUMN IF NOT EXISTS has_data boolean;
ALTER TABLE business ADD COLUMN IF NOT EXISTS created_at timestamp;
ALTER TABLE business ADD COLUMN IF NOT EXISTS updated_at timestamp;

UPDATE business
SET mobile = RIGHT(REGEXP_REPLACE(phone, '[^0-9]', '', 'g'), 10)
WHERE mobile IS NULL AND phone IS NOT NULL;

UPDATE business
SET gst_number = UPPER(gstin)
WHERE gst_number IS NULL AND gstin IS NOT NULL;

UPDATE business
SET created_at = CURRENT_TIMESTAMP
WHERE created_at IS NULL;

UPDATE business
SET has_data = FALSE
WHERE has_data IS NULL;
